<script setup lang="ts">
import { computed, ref } from 'vue';
import { useStore } from 'vuex';
import { useI18n } from '@shell/composables/useI18n';
import { useShell } from '@shell/apis';
import { NotificationLevel } from '@shell/types/notifications';
import { Checkbox } from '@components/Form/Checkbox';
import { isTemplatingEnabled, toggleTemplating } from '../templating/template-engine';
import { definePrefs } from '../templating/user-prefs';

// Configurable Views settings — each person's own on/off switch for the configurable pages. Always
// reachable (even when off) so they can be turned back on.

const store = useStore();
const { t } = useI18n(store);
const shell = useShell();

definePrefs(store);

const toggling = ref(false);

const enabled = computed(() => isTemplatingEnabled(store.getters));

async function onToggle(value: boolean): Promise<void> {
  if (toggling.value) {
    return;
  }
  toggling.value = true;

  try {
    const now = await toggleTemplating(store, value);

    shell.notification.send(NotificationLevel.Success, t('configurableViews.toggle.title'), now ? t('configurableViews.toggle.turnedOn') : t('configurableViews.toggle.turnedOff'));
  } catch (e) {
    shell.notification.send(NotificationLevel.Error, t('configurableViews.toggle.failed'), (e as Error)?.message || String(e));
  } finally {
    toggling.value = false;
  }
}
</script>

<template>
  <div class="configurable-views-settings">
    <h1 class="mb-10">
      {{ t('configurableViews.toggle.title') }}
    </h1>
    <p class="text-muted mb-20">
      {{ t('configurableViews.settings.intro') }}
    </p>

    <div
      class="templating-switch"
      :class="{ 'templating-switch--off': !enabled }"
    >
      <Checkbox
        :value="enabled"
        :disabled="toggling"
        :label="t('configurableViews.settings.enabled')"
        @update:value="onToggle"
      />
      <p class="text-muted mt-5 mb-0">
        {{ t('configurableViews.settings.enabledHint') }}
      </p>
    </div>
  </div>
</template>

